sys_variable_value.value:
function execute(inputs, outputs) {

    var list = inputs.approver_list + '';
    var arr = [];

    if (list) {
        var users = list.split(',');

        for (var i = 0; i < users.length; i++) {
            if (users[i]) {
                arr.push(users[i].trim());
            }
        }
    }

    outputs.approvers = arr;
}

